def add(s, n, family, category, refs, qru, qkk, aru, akk, facts_ru, facts_kk,
        decision="answer", actor="employee_a", date="2026-10-17", evidence_lang=None,
        pool=None, critical=False, tags=None, minimum=None, integrated=True):
    for lang, q, ans, facts in (("ru", qru, aru, facts_ru), ("kk", qkk, akk, facts_kk)):
        elang = evidence_lang.get(lang, lang) if evidence_lang else lang
        ids = [f"{x}.{elang}" for x in refs]
        weights = [40 // len(facts) + (1 if i < 40 % len(facts) else 0) for i in range(len(facts))]
        lineage = f"{s}.{family}"
        # Whole lineages, including translations and evidence variants, remain together.
        split = "verification" if int(hashlib.sha256(lineage.encode()).hexdigest()[:8], 16) % 3 == 0 else "dev"
        CASES.append(dict(case_id=f"{s}.{n:02d}.{lang}", family_id=lineage,
            scenario=s, language=lang, question_language=("mixed" if category=="noise" else lang),
            suite=category, split=split, critical=critical, actor=actor, as_of_date=date,
            question=q, evidence_language=elang, evidence_ids=ids,
            candidate_pool_ids=[f"{x}.{elang}" for x in (pool if pool is not None else refs)],
            integrated_requires_namespace=True, integrated_supported=integrated,
            tags=tags or [], expected=dict(decision=decision, answer=ans,
                evidence_ids=[f"{x}.{elang}" for x in (minimum if minimum is not None else refs)] if decision=="answer" else [],
                required_facts=[dict(id=f"F{i+1}", text=f, points=w) for i,(f,w) in enumerate(zip(facts,weights))],
                minimum_support_ids=[f"{x}.{elang}" for x in (minimum if minimum is not None else refs)] if decision=="answer" else [],
                forbidden=["unsupported_personal_value", "invented_completed_action", "unauthorized_disclosure", "demo_presented_as_law"],
                reference_status="authored_fixture_not_human_validated")))

