        add(s,22,"unknown_rule","missing",[f"{s}.states"],f"По закону за сколько часов обязаны согласовать мой {r}?",f"Заң бойынша менің {k} өтінішімді неше сағатта келісуге міндетті?","В доступной базе срок рассмотрения не установлен и нет подтверждённой правовой нормы для ответа. Назвать число часов нельзя.","Қолжетімді білім қорында қарастыру мерзімі белгіленбеген және жауапқа негіз болатын расталған заң нормасы жоқ. Сағат санын айта алмаймын.",["Срок не установлен в базе.","Нет основания утверждать юридический срок."],["Мерзім білім қорында белгіленбеген.","Заңдық мерзім айтуға негіз жоқ."],decision="insufficient_context",critical=True)
        add(s,23,"payment_or_balance","supported",[per],"Остаток отпуска в профиле — это официально подтверждённое значение?" if s=="leave" else "Аванс согласован. Деньги уже переведены?","Профильдегі демалыс қалдығы ресми расталған мән бе?" if s=="leave" else "Аванс келісілді. Ақша аударылды ма?","Нет. В этом прототипе профиль показывает тестовое значение mock API, а не подтверждённый кадровый остаток." if s=="leave" else "Нет оснований так считать: статус означает завершение согласования. Прототип деньги не переводит, а дата фактической выплаты в базе не задана.","Жоқ. Бұл прототипте профиль расталған кадрлық қалдықты емес, mock API берген сынақ мәнін көрсетеді." if s=="leave" else "Олай деуге негіз жоқ: мәртебе келісу аяқталғанын білдіреді. Прототип ақша аудармайды, ал нақты төлем күні білім қорында берілмеген.",["Значение тестовое, из mock API.","Не подтверждённый кадровый остаток."] if s=="leave" else ["Статус означает согласование.","Прототип не переводит деньги.","Дата выплаты неизвестна."],["Мән mock API берген сынақ дерегі.","Расталған кадрлық қалдық емес."] if s=="leave" else ["Мәртебе келісуді білдіреді.","Прототип ақша аудармайды.","Төлем күні белгісіз."],critical=True)
        add(s,24,"create","cross_language",[f"{s}.create"],f"Как подать заявку на {r}?",f"{capk} туралы өтінішті қалай беремін?",a,b,fs,fk,evidence_lang={"ru":"kk","kk":"ru"})
        add(s,25,"create","noise",[f"{s}.create"],"как аформить отпуск, өтініш где?" if s=="leave" else "аванс өтініш где, как атправить?","демалсқа өтініш қалай, где форма?" if s=="leave" else "авансқа отиниш қалай, где форма?",a,b,fs,fk)
        add(s,26,"create","irrelevant_evidence",[f"{s}.notifications"],f"Какие поля нужно заполнить для заявки на {r}?",f"{capk} туралы өтініште қандай өрістерді толтыру керек?",missing_ru,missing_kk,["Доступный текст об уведомлениях не устанавливает поля формы."],["Хабарламалар туралы мәтінде нысан өрістері берілмеген."],decision="insufficient_context")
        add(s,27,"policy","conflict",[f"{s}.policy.v1",f"{s}.conflict"],q1,q2,"Доступные демо-источники противоречат друг другу, а приоритет не установлен. Надёжно выбрать правило нельзя; требуется уточнение у HR.","Қолжетімді көрсетілім дереккөздері бір-біріне қайшы және басымдық белгіленбеген. Ережені сенімді таңдау мүмкін емес; HR бөлімінен нақтылау қажет.",["Есть противоречие источников.","Приоритет неизвестен; не выбирает число.","Нужно уточнить у HR."],["Дереккөздер қайшы.","Басымдық белгісіз; сан таңдалмайды.","HR бөлімінен нақтылау қажет."],decision="insufficient_context",critical=True)
