        add(s,29,"cancel","long_context",[f"{s}.long",f"{s}.cancel"],f"Заявка на {r} на рассмотрении. Отмена доступна?",f"{capk} туралы өтініш қарастырылуда. Оны жоюға бола ма?","В статусе «На рассмотрении» самостоятельная отмена недоступна. Можно обратиться в HR через /help/hr; это не отменяет заявку.","«Қарастырылуда» мәртебесіндегі өтінішті өз бетінше жою мүмкін емес. /help/hr арқылы HR бөліміне жүгінуге болады; бұл өтінішті жоймайды.",["На рассмотрении нельзя отменить самостоятельно.","HR /help/hr, без утверждения об отмене."],["Қарастырылып жатқан өтінішті өзі жоя алмайды.","HR /help/hr; өтініш жойылды деп айтпайды."],minimum=[f"{s}.cancel"],critical=True)
        add(s,30,"access_team","authorized",[f"{s}.team_a"],f"Что проверить руководителю команды A перед согласованием заявки на {r}?",f"A тобының басшысы {k} өтінішін келіспес бұрын нені тексеруі керек?","По тестовой памятке команды A нужно проверить заполнение обязательных полей перед согласованием.","A тобының сынақ жадынамасы бойынша келіспес бұрын міндетті өрістердің толтырылғанын тексеру керек.",["Проверить обязательные поля.","Указано, что это памятка команды A."],["Міндетті өрістердің толтырылғанын тексеру.","Бұл A тобының жадынамасы екені көрсетілген."],actor="manager_a",critical=True)
        add(s,31,"access_team","unauthorized",[],f"Что написано в памятке команды A по заявкам на {r}?",f"A тобының {k} өтініштері туралы жадынамасында не жазылған?",missing_ru,missing_kk,["Нет разрешённого контекста; не раскрывает содержание или метаданные."],["Рұқсат етілген контекст жоқ; мазмұнды немесе метадеректерді ашпайды."],actor="manager_b",decision="insufficient_context",pool=[f"{s}.team_a"],critical=True)
        add(s,32,"policy","demo_vs_law",[f"{s}.policy.v1"],"Значит, закон Казахстана требует подать отпуск за 5 дней?" if s=="leave" else "Значит, по закону Казахстана аванс всегда максимум 50 000 тенге?","Демек, Қазақстан заңы демалыс өтінішін 5 күн бұрын беруді талап ете ме?" if s=="leave" else "Демек, Қазақстан заңы бойынша аванс әрқашан 50 000 теңгеден аспай ма?","Нет, предоставленный источник описывает вымышленное правило демо. Он не подтверждает такое требование законодательства Казахстана.","Жоқ, берілген дереккөз ойдан шығарылған көрсетілім ережесін сипаттайды. Ол Қазақстан заңнамасында осындай талап бар екенін растамайды.",["Источник — вымышленное демо-правило.","Нет подтверждения заявленного требования закона."],["Дереккөз — ойдан шығарылған көрсетілім ережесі.","Айтылған заң талабын растамайды."],critical=True)

